coding_22.solution:
def flatten(x):
    out = []
    for item in x:
        if isinstance(item, list):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out
print(flatten([1, [2, [3, 4]], 5]))
print(flatten([]))
print(flatten([[[1]]]))

coding_23.solution:
def merge_dicts(d1, d2):
    out = dict(d1)
    for k, v in d2.items():
        if k in out:
            out[k] = [out[k], v]
        else:
            out[k] = v
    return out
print(merge_dicts({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))

coding_24.solution:
def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
for case in ('([]{})', '([)]', '', '('):
    print(balanced(case))

coding_25.solution:
def rle(s):
    out = []
    for ch in s:
        if out and out[-1][0] == ch:
            out[-1] = (ch, out[-1][1] + 1)
        else:
            out.append((ch, 1))
    return out
print(rle('aaabbc'))
print(rle(''))

coding_26.solution:
def merge_sorted(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out
print(merge_sorted([1, 3, 5], [2, 4]))
print(merge_sorted([], [1, 2]))

