def group_by_first(words):
    out = {}
    for w in words:
        if not w:
            continue
        out.setdefault(w[0], []).append(w)
    return out
print(group_by_first(['ant', 'bee', 'ape']))
print(group_by_first([]))

coding_28.solution:
def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        v = vals[ch]
        if i + 1 < len(s) and v < vals[s[i + 1]]:
            total -= v
        else:
            total += v
    return total
for case in ('XIV', 'MCMXC', 'IX', 'I'):
    print(roman_to_int(case))

