def transpose(m):
    if not m:
        return []
    n = len(m[0])
    if any(len(row) != n for row in m):
        return None
    return [[row[i] for row in m] for i in range(n)]
print(transpose([[1, 2], [3, 4], [5, 6]]))
print(transpose([[1, 2], [3]]))
